create table if not exists public.activities (
  id bigint generated by default as identity primary key,
  attraction_id bigint not null references public.attractions(id) on delete cascade,
  slug text not null unique,
  name text not null,
  location_name text,
  listing_summary text not null,
  detail_intro text,
  full_description text,
  highlights jsonb not null default '[]'::jsonb,
  best_time text,
  practical_info text,
  hero_image_url text,
  hero_image_alt text,
  gallery jsonb,
  booking_url text,
  source_url text,
  featured boolean not null default false,
  sort_order integer not null default 0,
  status text not null default 'draft' check (status in ('draft','published')),
  published_at timestamptz,
  meta_title text,
  meta_description text,
  meta_image_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists activities_attraction_idx on public.activities(attraction_id, sort_order);

create table if not exists public.travel_articles (
  id bigint generated by default as identity primary key,
  slug text not null unique,
  title text not null,
  category text,
  region text,
  country text,
  excerpt text not null,
  body text not null default '',
  read_time text,
  hero_image_url text,
  hero_image_alt text,
  video_url text,
  source_url text,
  featured boolean not null default false,
  sort_order integer not null default 0,
  status text not null default 'draft' check (status in ('draft','published')),
  published_at timestamptz,
  meta_title text,
  meta_description text,
  meta_image_url text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists travel_articles_publication_idx on public.travel_articles(status, published_at, featured, sort_order);

create trigger activities_set_updated_at before update on public.activities for each row execute function public.set_updated_at();
create trigger travel_articles_set_updated_at before update on public.travel_articles for each row execute function public.set_updated_at();

alter table public.activities enable row level security;
alter table public.travel_articles enable row level security;
revoke all on public.activities, public.travel_articles from anon, authenticated;
grant select on public.activities, public.travel_articles to anon, authenticated;
grant insert, update, delete on public.activities, public.travel_articles to authenticated;
grant usage on sequence public.activities_id_seq, public.travel_articles_id_seq to authenticated;
create policy "Public can read published activities" on public.activities for select to anon, authenticated
  using (status = 'published' and (published_at is null or published_at <= now()));
create policy "CMS staff can inspect activities" on public.activities for select to authenticated
  using ((select private.has_cms_role(array['viewer','editor','admin','super_admin'])));
create policy "Editors insert draft activities" on public.activities for insert to authenticated
  with check ((select private.has_cms_role(array['editor'])) and status = 'draft');
create policy "Editors update draft activities" on public.activities for update to authenticated
  using ((select private.has_cms_role(array['editor'])) and status = 'draft') with check ((select private.has_cms_role(array['editor'])) and status = 'draft');
create policy "Admins manage activities" on public.activities for all to authenticated
  using ((select private.has_cms_role(array['admin','super_admin']))) with check ((select private.has_cms_role(array['admin','super_admin'])));
create policy "Public can read published travel articles" on public.travel_articles for select to anon, authenticated
  using (status = 'published' and (published_at is null or published_at <= now()));
create policy "CMS staff can inspect travel articles" on public.travel_articles for select to authenticated
  using ((select private.has_cms_role(array['viewer','editor','admin','super_admin'])));
create policy "Editors insert draft travel articles" on public.travel_articles for insert to authenticated
  with check ((select private.has_cms_role(array['editor'])) and status = 'draft');
create policy "Editors update draft travel articles" on public.travel_articles for update to authenticated
  using ((select private.has_cms_role(array['editor'])) and status = 'draft') with check ((select private.has_cms_role(array['editor'])) and status = 'draft');
create policy "Admins manage travel articles" on public.travel_articles for all to authenticated
  using ((select private.has_cms_role(array['admin','super_admin']))) with check ((select private.has_cms_role(array['admin','super_admin'])));

-- Examples are tied to attractions already present in the catalogue. Provider URLs
-- below resolve to specific GetYourGuide experiences checked on 2026-09-30.
insert into public.activities (attraction_id, slug, name, location_name, listing_summary, full_description, highlights, best_time, practical_info, hero_image_url, hero_image_alt, booking_url, source_url, featured, sort_order, status, published_at)
select a.id, d.slug, d.name, a.location_name, d.summary, d.description, d.highlights::jsonb, d.best_time, d.notes, a.hero_image_url, a.hero_image_alt, d.booking_url, d.official_url, true, d.sort_order::integer, 'published', now()
from (values
 ('maasai-mara','maasai-mara-balloon-safari','Sunrise hot-air balloon safari','Maasai Mara National Reserve','See the Mara’s broad savannah from above on a sunrise balloon flight.','A pre-dawn launch gives a quiet aerial perspective over the Maasai Mara, followed by a landing breakfast. Flights are weather dependent and the operator sets the exact launch location and transfer plan.','["Pre-dawn transfer and launch","Aerial views across the Mara ecosystem","Landing breakfast included on the linked experience"]','Balloon flights are offered seasonally and depend on weather; confirm the operating dates and launch point with the provider.','Confirm pickup, baggage limits, age and health requirements, cancellation terms, and whether reserve fees are included. Balloon activity requires an approved operator and may be cancelled for unsafe wind.','https://www.getyourguide.com/kenya-l169122/maasai-mara-hot-air-balloon-safari-champagne-breakfast-t539006/','https://www.getyourguide.com/kenya-l169122/maasai-mara-hot-air-balloon-safari-champagne-breakfast-t539006/','https://www.magicalkenya.com/','1'),
 ('bwindi-impenetrable-national-park','bwindi-gorilla-trekking','Mountain gorilla trekking','Bwindi Impenetrable National Park','A guided forest trek to visit one habituated mountain-gorilla family.','Visitors trek with Uganda Wildlife Authority guides and trackers from one of Bwindi’s four sectors. The walk can take several hours over steep, muddy forest trails; time with the gorillas is limited under conservation rules.','["Small guided trekking group","One hour with the assigned gorilla family","Four sectors: Buhoma, Ruhija, Rushaga, and Nkuringo"]','Trekking operates year-round. Drier periods can mean easier footing, but rain is possible in the forest in any season.','A UWA permit must be secured for the correct sector and date; confirm age and health rules, fitness expectations, transport, and permit inclusion before payment. Follow ranger instructions and maintain the required wildlife distance.','https://www.getyourguide.com/western-region-uganda-l118965/bwindi-impenetrable-national-park-gorilla-trekking-day-trip-t860183/','https://www.getyourguide.com/western-region-uganda-l118965/bwindi-impenetrable-national-park-gorilla-trekking-day-trip-t860183/','https://ugandawildlife.org/activities/gorilla-tracking/','2'),
 ('amboseli-national-park','amboseli-game-drive-safari','Guided wildlife game drives','Amboseli National Park','Explore Amboseli’s wetlands and open plains on a guided safari drive.','A guided game drive follows established roads through Amboseli’s varied habitats, where elephants and birdlife are major draws. Clear Kilimanjaro views depend on weather, and wildlife sightings are never guaranteed.','["Elephant habitat and seasonal wetlands","Birdwatching across an important bird area","Views toward Mount Kilimanjaro when skies are clear"]','Early mornings and late afternoons are standard game-drive periods. The dry season often concentrates animals around water, while greener months can suit birding.','Use a licensed guide and vehicle, check park gate hours and current entry charges with KWS, stay on roads, and remain in the vehicle except at designated viewpoints.','https://www.getyourguide.com/kenya-l169122/from-nairobi-2-day-amboseli-national-park-safari-t849496/','https://www.getyourguide.com/kenya-l169122/from-nairobi-2-day-amboseli-national-park-safari-t849496/','https://kws.go.ke/park/amboseli-national-park/','3'),
 ('marrakech-and-atlas','atlas-mountains-day-trip','Atlas Mountains guided day trip','High Atlas Mountains, Morocco','Leave Marrakech for a guided mountain day among Atlas valleys and villages.','A full-day guided trip from Marrakech can combine mountain scenery, valley stops, a village walk, and a meal. The linked GetYourGuide experience describes a multi-valley outing; confirm the current itinerary, operator, and community stops directly.','["Scenic drive from Marrakech","Stops in Atlas valleys and mountain villages","Guided cultural context and local meal on the linked tour"]','Spring and autumn are generally comfortable for walking; winter conditions at elevation and summer heat at lower elevations require checking before departure.','Ask about walking distance and surface, pickup arrangements, meal inclusions, and whether the route is affected by weather or road conditions. Choose respectful, locally guided visits.','https://www.getyourguide.com/marrakech-l208/marrakech-atlas-mountains-5-valleys-day-tour-with-lunch-t11542/','https://www.getyourguide.com/marrakech-l208/marrakech-atlas-mountains-5-valleys-day-tour-with-lunch-t11542/','https://www.visitmorocco.com/','4')
) as d(attraction_slug,slug,name,location_name,summary,description,highlights,best_time,notes,booking_url,source_url,official_url,sort_order)
join public.attractions a on a.slug=d.attraction_slug
on conflict (slug) do nothing;

insert into public.activities (attraction_id,slug,name,location_name,listing_summary,full_description,highlights,best_time,practical_info,hero_image_url,hero_image_alt,booking_url,source_url,sort_order,status,published_at)
select a.id,d.slug,d.name,a.location_name,d.summary,d.description,d.highlights::jsonb,d.best_time,d.notes,a.hero_image_url,a.hero_image_alt,d.booking_url,d.source_url,d.sort_order,'published',now()
from (values
('serengeti-national-park','serengeti-balloon-safari','Serengeti balloon safari at dawn','See the Serengeti plains at first light, followed by breakfast in the bush.','A pre-dawn transfer brings you to the launch site for a pilot briefing and a balloon flight over the plains. The wind determines the route, so each journey differs. The linked operator includes a bush breakfast after landing; wildlife sightings cannot be promised.','["Dawn flight over the plains","Pilot briefing and ground transfers","Bush breakfast after landing"]','Flights launch around sunrise when conditions allow. Choose the operating area to match your camp and travel month; scenery and wildlife vary through the year.','Confirm your camp pickup, launch area, current passenger requirements, weather cancellation terms and park entry arrangements. Park entry is excluded from the linked experience. Wear layers for the cool early start.','https://www.getyourguide.com/serengeti-national-park-l123040/serengeti-national-park-balloon-safari-at-dawn-t383490/','https://www.balloonsafaris.com/faqs',5),
('cape-town','table-mountain-guided-hike','Table Mountain guided hike','Walk Table Mountain with a guide for coastal views and an introduction to its mountain ecology.','Explore the mountain on foot with a guide who explains the landscape and its plants. Select a route that fits your ability and allow time for changing weather. The linked guided experience focuses on mountain ecology; agree the route and return arrangements before booking.','["Guided mountain walk","Fynbos and landscape interpretation","Views over Cape Town when weather allows"]','Choose a clear-weather day and start early to leave enough daylight. Wind, heat, cloud and rain can change plans in any season; check the forecast and park advice with your guide.','Follow SANParks hiking guidance: travel in a group, keep to marked paths, take water and weatherproof clothing, and tell someone your route. Ask about route difficulty and whether cableway tickets or transfers are included.','https://www.getyourguide.com/en-au/cape-town-l103/table-mountain-immersive-guided-hike-with-an-eco-specialist-t836611/','https://www.sanparks.org/parks/table-mountain/useful-information/safe-hiking',6)
) as d(attraction_slug,slug,name,summary,description,highlights,best_time,notes,booking_url,source_url,sort_order)
join public.attractions a on a.slug=d.attraction_slug
on conflict (slug) do nothing;

-- Existing editorial titles and excerpts are expanded into short, editable guides.
-- Reading times are calculated from the actual body on the frontend.
insert into public.travel_articles (slug,title,category,region,country,excerpt,body,read_time,hero_image_url,hero_image_alt,featured,sort_order,status,published_at,source_url)
values
('plan-first-east-africa-safari','How to Plan Your First East Africa Safari','Planning Tips','east-africa','Uganda, Kenya, Tanzania & Rwanda','How to choose between Uganda, Kenya, Tanzania, and Rwanda depending on wildlife goals, road time, and budget.','<p>Start with the experience you most want, then build the route around it. Uganda is a strong choice when gorilla trekking or forest wildlife is central; Kenya and Tanzania suit classic savannah circuits; Rwanda can work well for a compact, premium primate-focused trip.</p><h2>Match the country to the priority</h2><p>Do not try to fit every country into one short visit. Compare permit availability, park distances, flight connections, and the number of nights you can give each region. A single country with time for several contrasting habitats often feels more rewarding than a string of rushed transfers.</p><h2>Plan around fixed logistics</h2><p>Secure limited permits and high-demand lodges before booking the rest of the route. Allow buffer time around domestic flights and long drives, and check official park rules and entry fees close to departure.</p><h2>Keep the itinerary realistic</h2><p>Talk with licensed local operators about road conditions, seasonal access, and the right vehicle. Build in rest after long travel days, and add a coast or city stay only when the transfers fit comfortably.</p>',null,'/images/stock/destinations/maasai-mara.jpg','Safari vehicle in East Africa',true,1,'published',now(),'https://ugandawildlife.org/activities/gorilla-tracking/'),
('uganda-vs-kenya-first-time-safari','Uganda vs Kenya for a First-Time Safari','Planning Tips','east-africa','Uganda & Kenya','Choose Uganda for gorillas and Nile scenery, Kenya for migration drama and classic savannah safaris.','<p>Uganda and Kenya suit different first safari priorities. Uganda combines savannah parks with forest trekking and the Nile; Kenya offers a broad choice of classic game-viewing areas, conservancies, and established safari routes.</p><h2>Choose Uganda for variety</h2><p>Uganda makes sense when mountain gorilla tracking is a central goal and you want to connect it with chimpanzees, river landscapes, or savannah wildlife. Gorilla permits and sector availability set the schedule, so plan those first.</p><h2>Choose Kenya for classic safari range</h2><p>Kenya offers a wide range of parks and conservancies. The Maasai Mara is famous for its wildlife and seasonal migration movement, while Amboseli pairs elephant habitat with dramatic mountain scenery. A good itinerary still needs realistic driving times between areas.</p><h2>Make the decision practical</h2><p>Compare total trip length, permit and park costs, flight access, and the style of guiding you prefer. Current fees, advice, and availability should be confirmed with official authorities and licensed operators.</p>',null,'/images/stock/destinations/bwindi-impenetrable-national-park.jpg','Forest landscape in Uganda',false,2,'published',now(),'https://kws.go.ke/wildlife-safaris/'),
('combine-serengeti-and-zanzibar','How to Combine Serengeti and Zanzibar Well','Itineraries','east-africa','Tanzania','A practical way to balance game-drive intensity with beach time, internal flights, and realistic pacing.','<p>Serengeti and Zanzibar pair well when the itinerary protects enough time for each. The Serengeti is vast, and the best wildlife location changes with season; Zanzibar adds Stone Town heritage and coastal time rather than functioning as a simple airport-side beach stop.</p><h2>Give the safari room</h2><p>Choose a Serengeti area based on the month and your route. Include time for transfers between the park, airstrip, and lodge, and ask an operator to explain what is and is not included in a fly-in safari.</p><h2>Use Zanzibar at a slower pace</h2><p>Allow at least a few nights to experience the island beyond a quick transfer. Stone Town and the beach districts have different characters; account for the extra flight and ground transfers when choosing where to stay.</p><h2>Check connections before confirming</h2><p>Flight schedules and luggage limits can change. Confirm current connections, park fees, and accommodation details before making non-refundable bookings.</p>',null,'/images/stock/destinations/zanzibar.jpg','Zanzibar coastline',false,3,'published',now(),'https://www.tanzaniaparks.go.tz/'),
('best-time-southern-africa','Best Time to Visit Southern Africa by Season','Best Time to Visit','southern-africa','South Africa, Botswana & Namibia','Dry-season wildlife and green-season scenery each offer different strengths across the region.','<p>Southern Africa does not have one universal best season. Rainfall, temperature, flood levels, road conditions, and park opening dates vary across South Africa, Botswana, Namibia, Zambia, and Zimbabwe.</p><h2>Compare the experience you want</h2><p>Drier months can make wildlife easier to see around water in some parks, while green periods bring young animals, dramatic skies, and strong birding. The Okavango flood cycle does not align perfectly with local rainfall, so check current seasonal guidance for each area.</p><h2>Build for conditions</h2><p>For a self-drive, consider heat, gravel-road distances, and daylight. For remote lodges, check camp operating calendars and flight access. Shoulder dates can be quieter, but some experiences run only during specific seasons.</p><h2>Verify before booking</h2><p>Confirm park status, weather-sensitive activities, and travel advice from official sources close to departure. Local conditions can vary widely within a single country.</p>',null,'/images/stock/destinations/okavango-delta.jpg','Okavango Delta landscape',false,4,'published',now(),'https://www.sanparks.org/'),
('cape-town-before-or-after-safari','Cape Town Before or After Safari?','Planning Tips','southern-africa','South Africa','When to place Cape Town in the route, how many nights to allow, and who benefits from the city-and-safari pairing.','<p>Cape Town works before or after a safari, depending on flight times and the kind of arrival day you prefer. Placing the city first can ease travelers into the trip; finishing there can provide a gentler transition home.</p><h2>Allow enough time</h2><p>Three or more nights give room for the city, Table Mountain or the peninsula, and a food or wine experience without turning each day into a race. Weather can affect mountain access and coastal plans.</p><h2>Protect your safari connections</h2><p>Keep a buffer before international departures after a domestic safari flight. Check current flight schedules and airport transfer times before booking onward travel.</p><h2>Choose by travel style</h2><p>Families, food travelers, and visitors who enjoy walkable urban days often appreciate Cape Town as a dedicated stay rather than a brief stopover.</p>',null,'/images/stock/destinations/cape-town.jpg','Cape Town and Table Mountain',false,5,'published',now(),'https://www.sanparks.org/') on conflict (slug) do nothing;

-- Preserve the other five legacy editorial titles and excerpts.
insert into public.travel_articles (slug,title,category,region,country,excerpt,body,hero_image_url,hero_image_alt,sort_order,status,published_at)
values
('morocco-sahara-itinerary','10-Day Morocco to Sahara Itinerary','Itineraries','north-africa','Morocco','From medinas to dunes with practical transport and camp planning.','<p>Use ten days to let the journey from Marrakech to the desert unfold at a comfortable pace. This is a suggested route, to adapt with a local operator once driving times and road conditions are confirmed.</p><h2>Days 1–3: settle into Marrakech</h2><p>Give the medina, gardens and quieter neighbourhoods separate pockets of time. Leave the arrival evening light, and arrange the mountain transfer before moving on.</p><h2>Days 4–5: cross the Atlas</h2><p>Break the journey around Ait Ben Haddou and the Ouarzazate area rather than rushing straight to the dunes. A local guide can add context to the architecture and landscape.</p><h2>Days 6–7: spend time in the desert</h2><p>Choose a camp and transfer arrangement that matches your comfort needs. Ask about facilities, walking or riding options, and the approach to the camp. Leave space for sunset and an unhurried morning.</p><h2>Days 8–10: return with a buffer</h2><p>Split the return drive and protect a final night before an international departure. The Moroccan tourism office also describes routes from Agadir and Fez; choose endpoints that fit your flights.</p>','https://images.unsplash.com/photo-1489493887464-892be6d1daae?auto=format&fit=crop&w=900&q=80','10-Day Morocco to Sahara Itinerary',6,'published',now()),
('cairo-giza-without-burning-out','Cairo and Giza Without Burning Out','Planning Tips','north-africa','Egypt','A smarter way to plan museums, pyramids, transfers, and evenings in Egypt’s busiest gateway.','<p>A rewarding Cairo stay needs pauses as much as major sights. Treat Giza, museums and city neighbourhoods as separate experiences rather than one long checklist.</p><h2>Plan by area</h2><p>Group nearby stops and ask your accommodation about realistic transfer times. Choose one main visit each day, then add a smaller outing only if you have the energy.</p><h2>Make room to look</h2><p>Give a museum or heritage site time for interpretation. A guide can help you select what matters to your interests instead of trying to see every room.</p><h2>Leave the evenings flexible</h2><p>A relaxed meal or a short local walk can balance a demanding day. Confirm current opening hours and tickets with each site before setting your schedule, and avoid a tight sightseeing plan before your departure flight.</p>','https://images.unsplash.com/photo-1539768942893-daf53e448371?auto=format&fit=crop&w=900&q=80','Cairo and Giza Without Burning Out',7,'published',now()),
('africa-trip-safety-basics','Safety Basics for Multi-Country Africa Trips','Safety','hybrid','Multi-country','Smart transport choices, emergency planning, and document backups.','<p>Prepare for each country and route separately. Conditions and entry requirements vary, so use your government travel-advice service and destination authorities for current guidance.</p><h2>Keep the essentials accessible</h2><p>Save copies of your travel documents separately from the originals, keep important contacts available offline, and give a trusted person your itinerary. Check that insurance covers the activities you plan to book.</p><h2>Make transport arrangements clear</h2><p>Confirm who is collecting you, where you will meet and how to contact your accommodation if plans change. Allow time between unfamiliar transfers and use providers you can verify.</p><h2>Revisit the plan before moving on</h2><p>Check official advice, local conditions and border requirements before each new stage. Ask a qualified travel-health professional about health preparations relevant to your itinerary.</p>','https://images.unsplash.com/photo-1527631746610-bca00a040d60?auto=format&fit=crop&w=900&q=80','Safety Basics for Multi-Country Africa Trips',8,'published',now()),
('cultural-etiquette-local-communities','Cultural Etiquette with Local Communities','Culture','west-africa','Senegal','Respect-first travel tips for villages, guides, and homestay hosts.','<p>Approach a community visit as time with people, not a performance. Let the host explain how the visit works and what is welcome.</p><h2>Ask before photographing</h2><p>Consent matters in homes, places of worship and everyday encounters. Respect a refusal and ask before sharing a photograph publicly.</p><h2>Let local hosts lead</h2><p>Confirm the price, what it supports and the expected duration beforehand. Follow guidance on dress, greetings and private spaces rather than assuming customs are the same across countries or communities.</p><h2>Choose an exchange that feels respectful</h2><p>Listen, leave time for questions, and buy goods or services directly where appropriate. Avoid treating children or families as attractions, and ask established local organisations about constructive ways to support their work.</p>','https://images.unsplash.com/photo-1509099836639-18ba1795216d?auto=format&fit=crop&w=900&q=80','Cultural Etiquette with Local Communities',9,'published',now()),
('ghana-senegal-slow-travel','Why Ghana and Senegal Work Well for Slow Travel','Culture','west-africa','Multi-country','How to approach West Africa with fewer checklist stops, more time on the ground, and stronger cultural payoff.','<p>A slower journey through Ghana or Senegal can give markets, food, history and everyday conversations room to become the centre of the trip. You do not need to combine both countries in one visit.</p><h2>Start with fewer bases</h2><p>Choose a city and one contrasting region, then allow several nights in each. Compare transfer time with the time you will actually spend exploring.</p><h2>Make space for local interpretation</h2><p>Visit heritage sites with a knowledgeable guide and leave time to reflect. Seek host-led experiences where expectations and payment are clear.</p><h2>Keep a flexible day</h2><p>A spare day can absorb a delayed transfer or make room for a place you want to revisit. Confirm current transport options and border requirements before committing to a multi-country route.</p>','https://images.unsplash.com/photo-1598875706250-21faaf804361?auto=format&fit=crop&w=900&q=80','Why Ghana and Senegal Work Well for Slow Travel',10,'published',now())
on conflict (slug) do nothing;

-- Official tourism film, embedded from its original publisher.
update public.travel_articles set video_url='https://www.youtube.com/watch?v=j38ijU7Kvzg' where slug='cape-town-before-or-after-safari' and video_url is null;

insert into public.page_sections (page_key,section_key,eyebrow,title,body,sort_order,status,published_at)
select 'travel-insights','hero','The Trek Africa journal','A little closer to Africa.','Places to linger. Stories to take with you. Practical ideas for a journey that feels your own.',0,'published',now()
where not exists (select 1 from public.page_sections where page_key='travel-insights' and section_key='hero');

-- Additional researched activities across the live destination catalogue.
insert into public.activities (attraction_id,slug,name,location_name,listing_summary,full_description,highlights,best_time,practical_info,hero_image_url,hero_image_alt,booking_url,source_url,sort_order,status,published_at)
select a.id,d.slug,d.name,a.location_name,d.summary,d.description,d.highlights::jsonb,d.best_time,d.notes,a.hero_image_url,a.hero_image_alt,d.booking_url,d.booking_url,d.sort_order,'published',now()
from (values
('cape-coast-kakum','cape-coast-kakum-guided-visit','Cape Coast heritage and Kakum visit','Combine a guided heritage visit with the forest canopy experience at Kakum.','The linked day tour connects Cape Coast and Elmina castles with Kakum National Park. Give the historical sites time for thoughtful interpretation, and ask the operator how the forest visit fits into a long day from Accra.','["Guided coastal heritage visits","Kakum forest and canopy experience","Transport between the featured stops"]','Choose an early departure to allow time at each stop. Confirm conditions for the canopy walk and plan around the weather on your date.','Check pickup, park and castle entry inclusions, walking requirements and the total driving time. The castles address the history of the slave trade; allow time to reflect.','https://www.getyourguide.com/de-de/accra-l506/accra-cape-coast-elmina-castles-kakum-park-tagestour-t481074/',7),
('victoria-falls','victoria-falls-guided-walk','Victoria Falls guided rainforest walk','Explore the Zimbabwe-side rainforest viewpoints with a local guide.','A guided walk through Victoria Falls National Park adds context to the river landscape and its viewpoints. Water levels, spray and visibility change, so ask which viewpoints are accessible during your visit.','["Rainforest paths and falls viewpoints","Local guiding and interpretation","Time for landscape photography"]','Plan in daylight and ask about current water levels. Choose your dates around whether you prefer stronger spray or clearer views, rather than expecting the same conditions year-round.','Confirm park entry fees, hotel pickup and which side of the border the tour visits. Take suitable footwear and protection for cameras in spray; stay on designated paths.','https://www.getyourguide.com/victoria-falls-town-l127068/victoria-falls-rainbow-guided-tour-t1182043/',8),
('okavango-delta','okavango-mokoro-safari','Okavango mokoro and wildlife safari','Experience delta waterways by mokoro as part of a guided multi-day safari.','The linked safari combines the Okavango Delta and Khwai area with game drives, guided walks and mokoro excursions. A mokoro outing offers a slower perspective on channels and islands, with the guide choosing a route suited to local conditions.','["Guided mokoro excursion","Delta and Khwai landscapes","Game drives within the linked itinerary"]','Water levels influence available routes. Ask the operator which areas are operating for your travel month and which activities are suitable in the current conditions.','The booking is a multi-day package, not a standalone canoe rental. Confirm accommodation, transfers, meals, conservation charges and the planned water activities before payment.','https://www.getyourguide.com/nl-nl/botswana-l169074/okavango-delta-tour-met-game-drives-mokoro-trips-t853076/',9),
('cairo-and-giza','giza-pyramids-guided-tour','Giza pyramids and museum guided tour','Connect the Giza pyramids and Sphinx with a guided museum visit.','A guided day connects the Giza plateau and the Grand Egyptian Museum. An Egyptologist guide provides context for the monuments and objects, while arranged transport helps connect the visits. Check the current itinerary and ticket inclusions before booking.','["Giza pyramids and Sphinx","Egyptologist-led interpretation","Grand Egyptian Museum visit"]','An early start leaves more time for outdoor stops before the warmest part of the day. Confirm site opening hours and the operator pickup time for your date.','Ask whether admission to the museum and pyramid interiors is included, and check the amount of walking, lunch arrangements and pickup area. Bring water and sun protection.','https://www.getyourguide.com/en-gb/giza-l915/cairo-giza-pyramids-the-grand-egyptian-museum-guided-tour-t448326/',10),
('volcanoes-national-park','volcanoes-gorilla-trek','Volcanoes National Park gorilla trekking','Join park rangers for a guided mountain-gorilla trekking experience in Rwanda.','A ranger-led trek searches for a habituated gorilla family in Volcanoes National Park. The walking time and terrain depend on the assigned group and its movements. Follow the briefing and wildlife-viewing rules throughout the encounter.','["Ranger-led forest trek","Mountain-gorilla observation","Volcanoes landscape and forest habitat"]','Plan around an available trekking permit and the required morning briefing. Ask the operator about expected trail conditions during your travel month; rain remains possible.','Confirm that the correct Rwanda permit is included: transport-only prices may exclude it. Check current age and health requirements with the park, disclose mobility needs, and agree Kigali pickup or an overnight stay near the park.','https://www.getyourguide.com/en-gb/volcanoes-national-park-rwanda-l144502/rwanda-gorilla-trekking-safaris-t890054/',11)
) as d(attraction_slug,slug,name,summary,description,highlights,best_time,notes,booking_url,sort_order)
join public.attractions a on a.slug=d.attraction_slug
on conflict (slug) do nothing;

insert into public.page_sections (page_key,section_key,eyebrow,title,body,image_url,sort_order,status,published_at)
select 'activities','hero','Activities','Choose the experiences that make the journey.','Explore activities connected to the attractions in our destination guides, with practical notes and booking links.','image-slot:attractions-index-hero',0,'published',now()
where not exists (select 1 from public.page_sections where page_key='activities' and section_key='hero');
